        terms["players.support.formula.net_worth"] = ("Pertumbuhan Kas = Koin Saat Ini ÷ Koin Awal × 100%.", "Cash Growth = Coins Held Now ÷ Starting Coins × 100%.");
        terms["players.support.formula.income_diversification"] = ("Rasio Diversifikasi Pendapatan = (Pendapatan Pekerjaan Bebas + Pendapatan Pesanan Makanan + Pendapatan Emas + Donasi Diterima) ÷ Total Pendapatan × 100%. Indeks Diversifikasi Pendapatan menunjukkan pemerataan antar-sumber.", "Income Diversification Ratio = (Freelance Income + Meal Income + Gold Income + Donations Received) ÷ Total Income × 100%. Income Diversification Index shows balance across sources.");
        terms["players.support.formula.income_diversification_index"] = ("Pemerataan Sumber Pendapatan = [1 − jumlah kuadrat setiap (Bagian Pendapatan ÷ 100)] ÷ [1 − (1 ÷ Jumlah Sumber Pendapatan Aktif)] × 100%. Jika hanya satu sumber aktif, hasilnya 0%. Jika tidak ada pemasukan, nilai tidak tersedia.", "Income Source Balance = [1 − the sum of squared (Income Share ÷ 100)] ÷ [1 − (1 ÷ Active Income Sources Count)] × 100%. With one active source the result is 0%. With no income, the value is unavailable.");
        terms["players.support.formula.expense_efficiency"] = ("Porsi Biaya Usaha = Total Investasi Koin Bahan ÷ Total Koin Keluar × 100%.", "Business Expense Share = Total Ingredient Coin Investment ÷ Total Cash Out × 100%.");
        terms["players.support.formula.business_margin"] = ("Margin Usaha Pesanan = (Total Pendapatan Pesanan − Biaya Bahan Terpakai) ÷ Total Pendapatan Pesanan × 100%.", "Order Business Margin = (Total Order Income − Used Ingredient Cost) ÷ Total Order Income × 100%.");
        terms["players.support.formula.business_efficiency"] = ("Pendapatan pesanan ÷ biaya bahan.", "Order income ÷ ingredient costs.");
        terms["players.support.formula.gold_roi"] = ("(Hasil penjualan emas − biaya pembelian emas) ÷ biaya pembelian × 100%.", "(Gold sale proceeds − gold purchase costs) ÷ purchase costs × 100%.");
        terms["players.support.formula.risk_exposure"] = ("Total biaya risiko ÷ total pemasukan × 100%.", "Total risk costs ÷ total income × 100%.");
        terms["players.support.formula.risk_mitigation"] = ("Risiko yang ditangani asuransi ÷ seluruh risiko yang terjadi × 100%.", "Risks covered by insurance ÷ all risks encountered × 100%.");
        terms["players.support.formula.risk_appetite"] = ("Kesiapan Menghadapi Risiko = Risiko Selesai tanpa Opsi Darurat ÷ Kartu Risiko Kehidupan yang Muncul × 100%.", "Risk Readiness = Risks Resolved without an Emergency Option ÷ Life Risk Cards Drawn × 100%.");
        terms["players.support.formula.debt_leverage"] = ("Beban Pinjaman = Sisa Pinjaman ÷ (Sisa Pinjaman + Aset Likuid) × 100%.", "Loan Burden = Outstanding Loan ÷ (Outstanding Loan + Liquid Assets) × 100%.");
        terms["players.support.formula.loan_discipline"] = ("Pinjaman yang lunas ÷ seluruh pinjaman yang diambil × 100%.", "Repaid loans ÷ all loans taken × 100%.");
        terms["players.support.formula.debt_ratio"] = ("Jumlah pinjaman belum lunas ÷ seluruh pinjaman yang diambil.", "Unpaid loans ÷ all loans taken.");
        terms["players.support.formula.goal_ambition"] = ("Target yang dicoba + (koin yang ditanamkan pada target ÷ kekayaan bersih akhir × 100). Indeks 0–100 yang lebih mudah dibandingkan ditampilkan terpisah.", "Goals attempted + (coins invested in goals ÷ ending net worth × 100). A separate 0–100 comparison index is also shown.");
        terms["players.support.formula.goal_ambition_index"] = ("Progres Target Finansial = Koin yang Dialokasikan ke Target ÷ Total Biaya Target yang Dicoba × 100%.", "Financial Goal Progress = Coins Committed to Goals ÷ Total Cost of Attempted Goals × 100%.");
        terms["players.support.formula.action_efficiency"] = ("Aksi yang Menghasilkan Uang = Aksi Penghasil Pemasukan ÷ Seluruh Aksi Pemain × 100%.", "Money-Earning Actions = Income-Producing Actions ÷ All Player Actions × 100%.");
        terms["players.support.formula.order_success"] = ("Pemanfaatan Bahan = Bahan yang Dipakai pada Pesanan Selesai ÷ Seluruh Bahan yang Dikumpulkan × 100%.", "Ingredient Utilization = Ingredients Used in Completed Orders ÷ All Ingredients Collected × 100%.");
        terms["players.support.formula.planning"] = ("Porsi Aksi Jangka Panjang = (Aksi Menabung + Target Finansial + Asuransi + Pembayaran Pinjaman) ÷ Seluruh Aksi Utama × 100%.", "Long-Term Action Share = (Savings + Financial Goal + Insurance + Loan Repayment Actions) ÷ All Main Actions × 100%.");
        terms["players.support.formula.fulfillment"] = ("Pemerataan Kebutuhan = [1 − ((Bagian Kebutuhan Primer ÷ 100)² + (Bagian Kebutuhan Sekunder ÷ 100)² + (Bagian Kebutuhan Tersier ÷ 100)²)] ÷ (1 − ⅓) × 100%.", "Need Balance = [1 − ((Primary Need Share ÷ 100)² + (Secondary Need Share ÷ 100)² + (Tertiary Need Share ÷ 100)²)] ÷ (1 − ⅓) × 100%.");
        terms["players.support.formula.fulfillment_document"] = ("√(jumlah primer² + jumlah sekunder² + jumlah tersier²) ÷ seluruh kartu kebutuhan × 100%.", "√(primary count² + secondary count² + tertiary count²) ÷ all need cards × 100%.");
        terms["players.support.formula.growth"] = ("Koin bersih akhir ÷ koin awal.", "Ending net coins ÷ starting coins.");
        terms["players.support.formula.donation_aggressiveness"] = ("Total koin donasi ÷ koin bersih akhir × 100%.", "Total donated coins ÷ ending net coins × 100%.");
        terms["players.support.formula.donation_stability"] = ("100 − simpangan baku nominal donasi, dibatasi 0–100%. Indeks konsistensi relatif terhadap rata-rata donasi ditampilkan terpisah.", "100 − the standard deviation of donation amounts, capped at 0–100%. A consistency index relative to the average donation is shown separately.");
        terms["players.support.formula.donation_stability_index"] = ("[1 − (simpangan baku ÷ rata-rata donasi)] × 100%, dibatasi 0–100%.", "[1 − (standard deviation ÷ average donation)] × 100%, capped at 0–100%.");
        terms["players.support.formula.donation_commitment"] = ("Konsistensi Donasi = Nilai Keteraturan Donasi × (Bagian Kas untuk Donasi ÷ 100) × (Keikutsertaan Hari Jumat ÷ 100), dibatasi 0–100.", "Donation Consistency = Donation Regularity × (Share of Cash Donated ÷ 100) × (Friday Participation ÷ 100), capped at 0–100.");
        terms["players.support.formula.happiness_portfolio"] = ("Total Poin Kebahagiaan = Poin Kartu Kebutuhan + Poin Bonus Set Kebutuhan + Poin Donasi + Poin Emas + Poin Pensiun + Poin Target Finansial + Poin Penalti Misi + Poin Penalti Pinjaman.", "Total Happiness Points = Need Cards Points + Need Set Bonus Points + Donation Points + Gold Points + Pension Points + Financial Goals Points + Mission Penalty Points + Loan Penalty Points.");
        terms["players.support.formula.happiness_portfolio.beginner"] = ("Total Poin Kebahagiaan = Poin Kartu Kebutuhan + Poin Bonus Set Kebutuhan + Poin Donasi + Poin Emas + Poin Pensiun + Poin Penalti Misi.", "Total Happiness Points = Need Cards Points + Need Set Bonus Points + Donation Points + Gold Points + Pension Points + Mission Penalty Points.");
